create extension if not exists pgcrypto;
create table users(id uuid primary key default gen_random_uuid(),name text not null,username text unique not null,password_hash text not null,role text not null check(role in('student','admin')),created_at timestamptz default now(),updated_at timestamptz default now());
create table student_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique references users on delete cascade,grade text,board text default 'CBSE',school text default 'Narayana',updated_at timestamptz default now());
create table subjects(id uuid primary key default gen_random_uuid(),name text unique not null,is_active bool default true,created_at timestamptz default now());
create table ai_configurations(id uuid primary key default gen_random_uuid(),agent_name text unique not null check(agent_name in('agent1','agent2','agent3','vision')),encrypted_api_key text,model_name text,system_prompt text,temperature real default 0.4,max_tokens int default 1024,updated_at timestamptz default now());
create table prompt_versions(id uuid primary key default gen_random_uuid(),agent_name text,prompt_content text,version_number int,academic_configuration_snapshot jsonb,created_at timestamptz default now(),created_by text);
create table question_sessions(id uuid primary key default gen_random_uuid(),student_id uuid references users,question_text text,ocr_text text,image_storage_path text,subject text,topic text,grade_snapshot text,board_snapshot text,question_type text,difficulty text,correct_answer text,solution_notes text,status text default 'In Progress' check(status in('In Progress','Solved','Given Up','Abandoned','Processing')),started_at timestamptz default now(),completed_at timestamptz,total_time_seconds int);
create table chat_messages(id uuid primary key default gen_random_uuid(),session_id uuid references question_sessions on delete cascade,sender text,message text,message_type text,created_at timestamptz default now());
create table student_attempts(id uuid primary key default gen_random_uuid(),session_id uuid references question_sessions on delete cascade,attempt_number int,submitted_answer text,is_correct bool,detected_mistake text,feedback text,created_at timestamptz default now());
create table hints(id uuid primary key default gen_random_uuid(),session_id uuid references question_sessions on delete cascade,hint_number int,hint_content text,created_at timestamptz default now());
create table question_analytics(id uuid primary key default gen_random_uuid(),session_id uuid unique references question_sessions on delete cascade,subject text,topic text,question_type text,difficulty text,hints_used int,incorrect_attempts int,time_spent int,final_status text,conceptual_score int,problem_solving_score int,formula_application_score int,numerical_accuracy_score int,mistake_categories jsonb,strengths jsonb,weaknesses jsonb,recommendations jsonb,analytical_summary text,analyzed_at timestamptz default now());
create table configuration_history(id uuid primary key default gen_random_uuid(),previous_configuration jsonb,new_configuration jsonb,changed_by text,created_at timestamptz default now());
create index on chat_messages(session_id,created_at);create index on hints(session_id);create index on student_attempts(session_id);
-- RLS enabled with no policies: only the server's service-role key can read/write.
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table %I enable row level security',t); end loop; end $$;
